ALTER TABLE public.assignations ALTER COLUMN employe_id DROP NOT NULL;
ALTER TABLE public.assignations ADD CONSTRAINT terrain_identite CHECK ((NOT terrain AND employe_id IS NOT NULL AND dispos_intervenant_id IS NULL) OR (terrain AND ((employe_id IS NOT NULL AND dispos_intervenant_id IS NULL) OR (employe_id IS NULL AND dispos_intervenant_id IS NOT NULL))));
CREATE OR REPLACE FUNCTION public.planning_terrain_semaine(_debut date,_fin date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT planning_terrain_lire_autorise() OR _fin<_debut OR _fin-_debut>31 THEN RAISE EXCEPTION 'Accès ou période invalide'; END IF; RETURN jsonb_build_object('references',planning_terrain_references(),'affectations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'employe_id',employe_id,'dispos_intervenant_id',dispos_intervenant_id,'etape_id',etape_logistique_id,'date',date,'affaire_id',affaire_id,'role',role_terrain,'validation',validation_logistique,'confirmation',statut_confirmation,'historique',historique_terrain)) FROM assignations WHERE date BETWEEN _debut AND _fin),'[]'::jsonb),'etapes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'date',e.date_debut,'fin',coalesce(e.date_fin,e.date_debut),'heure',e.heure_debut,'type',e.type,'nb_personnes',e.nb_personnes,'responsable',e.responsable,'lieu',coalesce(e.lieu_libre,a.lieu),'numero',a.numero,'nom',a.nom,'affaire_id',a.id)) FROM affaire_etapes_logistiques e JOIN affaires a ON a.id=e.affaire_id WHERE e.date_debut<=_fin AND coalesce(e.date_fin,e.date_debut)>=_debut AND e.statut<>'annule'),'[]'::jsonb),'dispos',coalesce((SELECT jsonb_agg(jsonb_build_object('intervenant_id',d.intervenant_id,'employe_id',i.employe_id,'jour',d.jour,'journee',d.journee,'soiree',d.soiree,'pas_dispo',d.pas_dispo)) FROM dispos_jours d JOIN dispos_intervenants i ON i.id=d.intervenant_id WHERE d.jour BETWEEN _debut AND _fin),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.planning_terrain_affecter(_etape uuid,_jour date,_personne uuid,_origine text,_role text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e affaire_etapes_logistiques; ident uuid; BEGIN IF NOT planning_terrain_ecrire_autorise() THEN RAISE EXCEPTION 'Accès refusé' USING ERRCODE='42501'; END IF; SELECT * INTO e FROM affaire_etapes_logistiques WHERE id=_etape FOR UPDATE; IF e.id IS NULL OR e.statut='annule' OR _jour<e.date_debut OR _jour>coalesce(e.date_fin,e.date_debut) OR _role NOT IN ('chef_equipe','equipier') THEN RAISE EXCEPTION 'Étape, date ou rôle invalide'; END IF; IF _origine='employe' THEN IF NOT EXISTS(SELECT 1 FROM employes WHERE id=_personne AND actif) THEN RAISE EXCEPTION 'Personne inexistante'; END IF; ELSIF _origine='dispos' THEN IF NOT EXISTS(SELECT 1 FROM dispos_intervenants WHERE id=_personne AND actif AND employe_id IS NULL) THEN RAISE EXCEPTION 'Intervenant invalide'; END IF; ELSE RAISE EXCEPTION 'Origine invalide'; END IF; SELECT id INTO ident FROM assignations WHERE etape_logistique_id=_etape AND date=_jour AND ((_origine='employe' AND employe_id=_personne) OR (_origine='dispos' AND dispos_intervenant_id=_personne)) LIMIT 1; IF ident IS NOT NULL THEN RETURN ident; END IF; INSERT INTO assignations(affaire_id,employe_id,dispos_intervenant_id,date,demi_journee,heures,terrain,etape_logistique_id,source_terrain,role_terrain,created_by,heure_debut,heure_fin) VALUES(e.affaire_id,CASE WHEN _origine='employe' THEN _personne END,CASE WHEN _origine='dispos' THEN _personne END,_jour,'JOURNEE',0,true,_etape,'manuelle',_role,auth.uid(),e.heure_debut,e.heure_fin) RETURNING id INTO ident; RETURN ident; END $$;
REVOKE ALL ON FUNCTION public.planning_terrain_semaine(date,date),public.planning_terrain_affecter(uuid,date,uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.planning_terrain_semaine(date,date),public.planning_terrain_affecter(uuid,date,uuid,text,text) TO authenticated;